<?php require_once __DIR__.'/../includes/auth.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);if($action==='delete'&&$id){$s=db()->prepare('DELETE FROM quiz_questions WHERE id=?');$s->bind_param('i',$id);$s->execute();flash('success','Question deleted.');header('Location: quiz_questions.php');exit;}if($action==='add'){$fields=['question_en','question_si','question_ta','option_a_en','option_a_si','option_a_ta','option_b_en','option_b_si','option_b_ta','option_c_en','option_c_si','option_c_ta','option_d_en','option_d_si','option_d_ta','explanation_en','explanation_si','explanation_ta'];$v=[];foreach($fields as $f)$v[$f]=trim((string)($_POST[$f]??''));$qid=(int)($_POST['quiz_id']??0);$correct=(string)($_POST['correct_option']??'');if($qid&&in_array($correct,['a','b','c','d'],true)&&!in_array('',array_values($v),true)){$cols=implode(',',array_keys($v));$marks=implode(',',array_fill(0,count($v),'?'));$s=db()->prepare("INSERT INTO quiz_questions(quiz_id,$cols,correct_option) VALUES(?,$marks,?)");$types='i'.str_repeat('s',count($v)+1);$args=array_merge([$qid],array_values($v),[$correct]);$s->bind_param($types,...$args);$s->execute();flash('success','Question added.');}else flash('error','Complete all multilingual fields.');header('Location: quiz_questions.php');exit;}}$pageTitle='Quiz questions';include __DIR__.'/_top.php';$quizzes=db()->query('SELECT id,title_en FROM quizzes ORDER BY title_en');$rows=db()->query('SELECT qq.id,qq.question_en,q.title_en FROM quiz_questions qq JOIN quizzes q ON q.id=qq.quiz_id ORDER BY qq.id DESC');?><h1>Multilingual quiz questions</h1><section class="card"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="add"><label>Quiz<select name="quiz_id"><?php while($q=$quizzes->fetch_assoc()):?><option value="<?=$q['id']?>"><?=e($q['title_en'])?></option><?php endwhile;?></select></label><?php foreach(['question'=>'Question','option_a'=>'Option A','option_b'=>'Option B','option_c'=>'Option C','option_d'=>'Option D','explanation'=>'Explanation'] as $base=>$label):foreach(['en'=>'English','si'=>'Sinhala','ta'=>'Tamil'] as $lang=>$ln):?><label><?=e($label.' · '.$ln)?><textarea name="<?=e($base.'_'.$lang)?>" required></textarea></label><?php endforeach;endforeach;?><label>Correct option<select name="correct_option"><option value="a">A</option><option value="b">B</option><option value="c">C</option><option value="d">D</option></select></label><button>Add question</button></form></section><section class="card scroll"><table><tr><th>Quiz</th><th>Question</th><th>Action</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['title_en'])?></td><td><?=e($r['question_en'])?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="danger" name="action" value="delete" onclick="return confirm('Delete this question?')">Delete</button></form></td></tr><?php endwhile;?></table></section><?php include __DIR__.'/../includes/footer.php';?>
